"""HTML report generated for Bruno runs.

The CSS and JavaScript are kept minified on purpose (one statement per line), which is why this module is exempt
from the line-length rule.
"""
import html


def render_report_html(embedded_results: str, fallback_results: str, run_name: str) -> str:
    """Self-contained report page; the results are embedded as JSON (already escaped for a <script> tag)."""
    return f"""<!doctype html><html><head><meta charset='utf-8'><title>Allure Report</title>
<style>
*{{box-sizing:border-box}}body{{font:14px system-ui,-apple-system,sans-serif;margin:0;background:#f5f7fb;color:#172033}}main{{max-width:1400px;margin:auto;padding:32px}}h1{{margin:0 0 4px}}.muted{{color:#667085}}.summary,.filters{{display:flex;flex-wrap:wrap;gap:10px;margin:20px 0}}.card,.case,.chart-card{{background:#fff;border:1px solid #dce3ee;border-radius:8px;box-shadow:0 1px 2px #1018280d}}.card{{padding:12px 16px;min-width:110px}}.count{{font-weight:700;font-size:20px}}button{{border:1px solid #ccd5e3;background:#fff;border-radius:6px;padding:7px 11px;cursor:pointer}}button.active{{background:#172033;color:white}}.charts{{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:14px;margin:18px 0}}.chart-card{{padding:14px}}.chart-card h2{{font-size:13px;margin:0 0 12px}}.pie-wrap{{display:flex;align-items:center;gap:16px}}.pie{{width:140px;height:140px;border-radius:50%;flex-shrink:0}}.legend{{display:flex;flex-direction:column;gap:6px;font-size:12px;min-width:0}}.legend-item{{display:flex;align-items:center;gap:6px}}.swatch{{width:10px;height:10px;border-radius:3px;flex-shrink:0}}.legend-label{{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:170px}}.bar-row{{display:grid;grid-template-columns:72px 1fr 36px;gap:8px;align-items:center;margin:8px 0;font-size:12px}}.bar-track{{height:12px;border-radius:99px;background:#edf1f6;overflow:hidden}}.bar{{height:100%;border-radius:99px}}.duration-chart{{display:flex;align-items:end;gap:6px;height:160px;border-bottom:1px solid #dce3ee;padding:8px 2px 0;overflow-x:auto}}.duration-item{{min-width:28px;height:100%;display:flex;flex-direction:column;justify-content:end;align-items:center;gap:4px}}.duration-bar{{width:22px;background:#3b82f6;border-radius:4px 4px 0 0;min-height:2px}}.duration-label{{font-size:9px;color:#667085;writing-mode:vertical-rl;transform:rotate(180deg);max-height:55px;overflow:hidden}}.case{{margin:10px 0;overflow:hidden}}.case summary{{display:flex;align-items:center;gap:10px;padding:13px;cursor:pointer;list-style:none}}.case summary::-webkit-details-marker{{display:none}}.name{{font-weight:650;flex:1;word-break:break-word}}.badge{{padding:3px 8px;border-radius:999px;font-size:11px;font-weight:700;text-transform:uppercase}}.passed{{background:#dcfae6;color:#087443}}.failed,.error{{background:#ffe1e0;color:#b42318}}.skipped{{background:#edf0f5;color:#526071}}.details{{border-top:1px solid #e4e9f2;padding:14px;background:#fafbfd}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:12px}}section{{border:1px solid #dce3ee;border-radius:7px;background:#fff;overflow:hidden}}section h3{{font-size:12px;margin:0;padding:10px 12px;background:#f2f5f9;border-bottom:1px solid #dce3ee}}pre{{margin:0;padding:12px;max-height:300px;overflow:auto;background:#101828;color:#d7e2f0;font:11px ui-monospace,SFMono-Regular,Menlo,monospace;white-space:pre-wrap;word-break:break-word}}.meta{{font-size:12px;color:#667085}}.assertions{{margin-top:12px}}.assertion{{padding:8px;border-top:1px solid #edf0f5}}.assertion:first-child{{border-top:0}}.chart-card{{cursor:zoom-in;transition:box-shadow .15s ease}}.chart-card:hover{{box-shadow:0 4px 14px #1018281a}}.chart-close{{display:none;position:absolute;top:10px;right:10px;width:28px;height:28px;align-items:center;justify-content:center;border:1px solid #ccd5e3;background:#fff;border-radius:6px;cursor:pointer;font-size:16px;line-height:1}}.chart-card.expanded{{position:fixed;top:50%;left:50%;z-index:1001;width:min(900px,calc(100vw - 32px));height:min(720px,calc(100vh - 32px));padding:24px;transform:translate(-50%,-50%);cursor:default;overflow:auto;display:flex;flex-direction:column;box-shadow:0 20px 60px #10182840}}.chart-card.expanded .chart-close{{display:flex}}.chart-card.expanded .pie-wrap{{flex:1;align-items:center;justify-content:center}}.chart-card.expanded .pie{{width:min(55vh,420px);height:min(55vh,420px)}}.chart-card.expanded .duration-chart{{flex:1;height:auto}}.chart-backdrop{{display:none;position:fixed;inset:0;background:#10182866;z-index:1000}}.chart-backdrop.show{{display:block}}
</style><style>.report-toolbar{{display:flex;justify-content:flex-end;margin-top:-28px}}.report-toolbar button{{font-size:12px}}.chart-tabs{{display:flex;justify-content:center;gap:6px;overflow-x:auto;margin:18px 0 0;padding-bottom:2px}}.chart-tabs button{{white-space:nowrap;font-size:12px}}.charts{{display:flex;align-items:center;justify-content:center;min-height:300px}}.charts .chart-card{{width:min(100%,760px)}}.charts .pie-wrap{{justify-content:center}}.charts .pie-wrap .legend{{align-items:center}}.charts .legend-item{{justify-content:center}}.charts .duration-chart{{justify-content:center}}.test-status-pie{{align-items:flex-start}}.test-status-pie .legend{{flex:0 1 460px;min-width:0}}.test-status-pie .legend-label{{max-width:360px;white-space:normal;overflow-wrap:anywhere;line-height:1.35}}.chart-card.expanded .test-status-pie{{align-items:center}}.chart-card.expanded .test-status-pie .legend-label{{max-width:min(52vw,620px);font-size:14px}}</style></head><body><main><h1>Allure Report</h1><p class='muted'>{html.escape(run_name)}</p><div class='report-toolbar'><button type='button' onclick='downloadReport()'>Download HTML</button></div><div id='summary' class='summary'></div><div id='chart-tabs' class='chart-tabs'></div><div id='charts' class='charts'></div><div id='chart-backdrop' class='chart-backdrop' onclick='closeAllCharts()'></div><div class='filters' id='filters'></div><div id='cases'></div></main>
<script>
const raw={embedded_results}; const fallback={fallback_results};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}}[c]));
const pretty=v=>typeof v==='string'?v:JSON.stringify(v??{{}},null,2);
const statusOf=r=>{{const assertions=[...(r.postResponseTestResults||[]),...(r.testResults||[])];return assertions.some(a=>a.status==='fail')||r.error?'failed':r.status==='skip'?'skipped':'passed'}};
const folderOf=p=>{{const parts=(p||'').split('/').filter(Boolean);return parts.length>1?parts[0]:'(root)'}};
const cases=raw.length?raw.map(r=>({{raw:r,name:r.name||r.test?.filename||'Unnamed request',status:statusOf(r),duration:r.response?.duration||r.response?.responseTime||Math.round((r.runDuration||0)*1000),httpStatus:r.response?.status?String(r.response.status):(r.error?'No response':'—'),method:r.request?.method||'—',folder:folderOf(r.path||r.suitename)}})):fallback.map(r=>({{raw:null,name:r.test_name||'Unnamed test',status:r.status||'error',duration:r.duration_ms||0,httpStatus:'—',method:'—',folder:'(root)',fallback:r}}));
const statuses=['all','passed','failed','skipped'];let active='all';let activeChart='test-status';
const PALETTE=['#3b82f6','#f59e0b','#10b981','#8b5cf6','#ec4899','#14b8a6','#f97316','#6366f1','#84cc16','#e11d48','#0ea5e9','#a855f7'];
const STATUS_COLORS={{passed:'#16a34a',failed:'#dc2626',skipped:'#64748b',error:'#dc2626'}};
function groupCounts(items,keyFn){{const map=new Map();for(const item of items){{const key=keyFn(item);map.set(key,(map.get(key)||0)+1)}}return [...map.entries()].sort((a,b)=>b[1]-a[1])}}
function pieChart(title,entries,colorFn){{const total=entries.reduce((s,[,v])=>s+v,0)||1;let acc=0;const stops=entries.map(([label,value],i)=>{{const start=acc/total*360;acc+=value;const end=acc/total*360;return `${{colorFn(label,i)}} ${{start}}deg ${{end}}deg`}}).join(',');const legend=entries.map(([label,value],i)=>`<div class="legend-item"><span class="swatch" style="background:${{colorFn(label,i)}}"></span><span class="legend-label" title="${{esc(label)}}">${{esc(label)}}</span><strong>${{value}}</strong><span class="muted">(${{Math.round(value/total*100)}}%)</span></div>`).join('');return `<div class="chart-card" onclick="toggleFullscreen(this)"><button class="chart-close" onclick="event.stopPropagation();closeAllCharts()" title="Exit full screen" aria-label="Exit full screen">✕</button><h2>${{esc(title)}}</h2><div class="pie-wrap"><div class="pie" style="background:conic-gradient(${{stops||'#edf1f6 0deg 360deg'}})"></div><div class="legend">${{legend||'<span class=\\'muted\\'>No data</span>'}}</div></div></div>`}}
function testStatusChart(items){{const total=items.length||1;let position=0;const slices=items.map(item=>{{const start=position/total*360;position+=1;const end=position/total*360;return `${{STATUS_COLORS[item.status]||'#64748b'}} ${{start}}deg ${{end}}deg`}}).join(',');const legend=items.map(item=>{{const color=STATUS_COLORS[item.status]||'#64748b';return `<div class="legend-item"><span class="swatch" style="background:${{color}}"></span><span class="legend-label" title="${{esc(item.name)}}">${{esc(item.name)}}</span><span class="test-status-value" style="color:${{color}}">${{esc(item.status)}}</span></div>`}}).join('')||'<span class="muted">No tests match this status.</span>';return `<div class="chart-card" onclick="toggleFullscreen(this)"><button class="chart-close" onclick="event.stopPropagation();closeAllCharts()" title="Exit full screen" aria-label="Exit full screen">✕</button><h2>Test Status by Test</h2><div class="pie-wrap test-status-pie"><div class="pie" style="background:conic-gradient(${{slices||'#edf1f6 0deg 360deg'}})"></div><div class="legend">${{legend}}</div></div></div>`}}
function render(){{const shown=active==='all'?cases:cases.filter(c=>c.status===active);const counts=Object.fromEntries(statuses.map(s=>[s,s==='all'?cases.length:cases.filter(c=>c.status===s).length]));document.getElementById('summary').innerHTML=statuses.map(s=>`<div class="card"><div class="count">${{counts[s]}}</div><div class="meta">${{s==='all'?'Total':s}}</div></div>`).join('');const maxDuration=Math.max(...shown.map(c=>c.duration),1);const byStatus=groupCounts(shown,c=>c.status);const byHttp=groupCounts(shown,c=>c.httpStatus);const byFolder=groupCounts(shown,c=>c.folder);const byMethod=groupCounts(shown,c=>c.method);const chartViews=[{{id:'test-status',label:'Test Status by Test',content:testStatusChart(shown)}},{{id:'status',label:'Status',content:pieChart('By Test Status',byStatus,l=>STATUS_COLORS[l]||'#94a3b8')}},{{id:'http',label:'HTTP Status',content:pieChart('By HTTP Status Code',byHttp,(l,i)=>l.startsWith('2')?'#16a34a':l.startsWith('4')?'#f59e0b':l.startsWith('5')?'#dc2626':PALETTE[i%PALETTE.length])}},{{id:'folder',label:'Collection / Folder',content:pieChart('By Collection / Folder',byFolder,(l,i)=>PALETTE[i%PALETTE.length])}},{{id:'method',label:'HTTP Method',content:pieChart('By HTTP Method',byMethod,(l,i)=>PALETTE[i%PALETTE.length])}},{{id:'duration',label:'Duration',content:`<div class="chart-card" onclick="toggleFullscreen(this)"><button class="chart-close" onclick="event.stopPropagation();closeAllCharts()" title="Exit full screen" aria-label="Exit full screen">✕</button><h2>Request Duration (${{active==='all'?'all statuses':active}})</h2><div class="duration-chart">${{shown.map(c=>`<div class="duration-item" title="${{esc(c.name)}}: ${{c.duration}} ms"><div class="duration-bar" style="height:${{Math.max(c.duration/maxDuration*125,2)}}px"></div><span class="duration-label">${{esc(c.name)}}</span></div>`).join('')}}</div></div>`}}];if(!chartViews.some(view=>view.id===activeChart))activeChart='test-status';document.getElementById('chart-tabs').innerHTML=chartViews.map(view=>`<button class="${{activeChart===view.id?'active':''}}" onclick="setChart('${{view.id}}')">${{view.label}}</button>`).join('');document.getElementById('charts').innerHTML=chartViews.find(view=>view.id===activeChart).content;document.getElementById('filters').innerHTML=statuses.map(s=>`<button class="${{active===s?'active':''}}" onclick="setFilter('${{s}}')">${{s==='all'?'All statuses':s}} (${{counts[s]}})</button>`).join('');document.getElementById('cases').innerHTML=shown.map((c,i)=>caseHtml(c,i)).join('')||'<p class="muted">No requests match this status.</p>'}}
function setFilter(s){{active=s;render()}}
function setChart(chart){{activeChart=chart;closeAllCharts();render()}}
function downloadReport(){{const html=document.documentElement.outerHTML;const blob=new Blob([html],{{type:'text/html;charset=utf-8'}});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='allure-report.html';document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url)}}
function toggleFullscreen(el){{if(!el)return;if(el.classList.contains('expanded')){{closeAllCharts();return}}document.querySelectorAll('.chart-card.expanded').forEach(c=>c.classList.remove('expanded'));el.classList.add('expanded');const backdrop=document.getElementById('chart-backdrop');if(backdrop)backdrop.classList.add('show')}}
function closeAllCharts(){{document.querySelectorAll('.chart-card.expanded').forEach(c=>c.classList.remove('expanded'));const backdrop=document.getElementById('chart-backdrop');if(backdrop)backdrop.classList.remove('show')}}
document.addEventListener('keydown',e=>{{if(e.key==='Escape')closeAllCharts()}});
function dataBlock(title,value){{return `<section><h3>${{title}}</h3><pre>${{esc(pretty(value))}}</pre></section>`}}
function caseHtml(c,i){{const r=c.raw;if(!r)return `<details class="case"><summary><span class="badge ${{c.status}}">${{c.status}}</span><span class="name">${{esc(c.name)}}</span><span class="meta">${{c.duration}} ms</span></summary><div class="details">${{dataBlock('Result',c.fallback)}}</div></details>`;const req=r.request||{{}},res=r.response||{{}},params=Object.fromEntries(new URLSearchParams((req.url||'').split('?')[1]||''));const assertions=[...(r.preRequestTestResults||[]),...(r.postResponseTestResults||[]),...(r.testResults||[])];const assertionHtml=assertions.length?`<section class="assertions"><h3>Assertions</h3>${{assertions.map(a=>`<div class="assertion"><span class="badge ${{a.status==='pass'?'passed':'failed'}}">${{esc(a.status)}}</span> <strong>${{esc(a.description||'Assertion')}}</strong>${{a.error?`<pre>${{esc(a.error)}}</pre>`:''}}</div>`).join('')}}</section>`:'';return `<details class="case"><summary><span class="badge ${{c.status}}">${{c.status}}</span><span class="name">${{esc(c.name)}}</span><span class="meta">${{esc(req.method||'')}} · ${{res.status||'—'}} · ${{c.duration}} ms</span></summary><div class="details"><div class="grid">${{dataBlock('Request URL',req.url||'')}}${{dataBlock('Request headers',req.headers||{{}})}}${{dataBlock('Request parameters',params)}}${{dataBlock('Request body',req.data||'')}}${{dataBlock('Response URL',res.url||req.url||'')}}${{dataBlock('Response status',{{status:res.status,statusText:res.statusText,duration:res.duration||res.responseTime,size:res.size}})}}${{dataBlock('Response headers',res.headers||{{}})}}${{dataBlock('Response body',res.data||'')}}</div>${{assertionHtml}}</div></details>`}}
render();
</script></body></html>"""
